#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Team {
    pub name: &'static str,
    pub points: u32,
    pub goal_diff: i32,
    pub goals_scored: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RankedTeam {
    pub rank: usize,
    pub name: &'static str,
    pub points: u32,
    pub goal_diff: i32,
    pub goals_scored: u32,
}

pub fn rank_teams(teams: &[Team]) -> Vec<RankedTeam> {
    let mut teams = teams.to_vec();
    teams.sort_by(|a, b| {
        b.points
            .cmp(&a.points)
            .then_with(|| {
                b.goal_diff
                    .cmp(&a.goal_diff)
                    .then_with(|| {
                        b.goals_scored
                            .cmp(&a.goals_scored)
                            .then_with(|| a.name.cmp(b.name))
                    })
            })
    });

    let mut seen: std::collections::BTreeSet<&str> = std::collections::BTreeSet::new();
    let mut ranks = std::iter::repeat(0);
    teams
        .into_iter()
        .map(|team| {
            let rank = if seen.contains(team.name) { ranks.next().unwrap() } else { ranks.next().unwrap() + 1 };
            seen.insert(team.name);
            RankedTeam {
                rank,
                name: team.name,
                points: team.points,
                goal_diff: team.goal_diff,
                goals_scored: team.goals_scored,
            }
        })
        .collect()
}

